// One-time repair of the four sign-ins generated by the 20 October access check.
// Refuses to remove entries unless every stored field matches the inspected events.
import { DatabaseSync } from "node:sqlite";
import { writeFileSync } from "node:fs";
import path from "node:path";
import assert from "node:assert/strict";

const expected = [
  ["2ebf3fb2-ae89-4dd7-a50d-1e3d26668df8", "aline", "2026-10-20T08:19:50.701Z"],
  ["5c4ff49a-cc91-44e1-8bc6-17b189a90004", "rabab-majzoub", "2026-10-20T08:19:50.761Z"],
  ["9041a9ee-b621-4e3e-90c2-9b25ca8084ed", "chadi-abdalla", "2026-10-20T08:19:50.816Z"],
  ["d0a8dd6b-8d9f-4dc4-89b4-1913e8a6b5c8", "mahdi-maatouk", "2026-10-20T08:19:50.872Z"],
];
const database = new DatabaseSync(path.join(process.cwd(), ".data", "dms.sqlite"));
try {
  database.exec("BEGIN IMMEDIATE");
  const events = expected.map(([id, userId, timestamp]) => {
    const row = database.prepare("SELECT * FROM audit_logs WHERE id = ?").get(id);
    assert(row, `Expected test entry ${id} is absent. No repair performed.`);
    const entry = JSON.parse(row.record);
    assert.equal(row.user_id, userId);
    assert.equal(row.timestamp, timestamp);
    assert.equal(row.document_id, null);
    assert.equal(entry.action, "sign-in");
    assert.equal(entry.description, "Signed in to DMS");
    assert.equal(entry.device, "Browser on device");
    assert.equal(entry.ipAddress, "::1");
    return row;
  });
  const backup = path.join(process.cwd(), ".data", "confirmed-test-signins-2026-10-20.json");
  writeFileSync(backup, JSON.stringify(events, null, 2), { flag: "wx", mode: 0o600 });
  for (const [id] of expected) database.prepare("DELETE FROM audit_logs WHERE id = ?").run(id);
  database.exec("COMMIT");
  console.log("Removed exactly four confirmed automated-test sign-ins. Recovery copy: .data/confirmed-test-signins-2026-10-20.json. Other events were preserved.");
} catch (error) { database.exec("ROLLBACK"); throw error; }
finally { database.close(); }
